// Independent PHP workers race canonical transitions and queue recovery.
function sn_race(array $jobs): array {
 $dir=sys_get_temp_dir().'/bvm-notify-race-'.wp_generate_uuid4();mkdir($dir);$procs=array();$pipes=array();$results=array();
 try {
  foreach($jobs as $i=>$job){$job['mail_log']=$dir.'/mail';$job['go']=$dir.'/go';file_put_contents($dir.'/job'.$i,json_encode($job));$procs[$i]=proc_open(array(PHP_BINARY,__DIR__.'/notification-worker.php',$dir.'/job'.$i,$dir.'/ready'.$i),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes[$i]);fclose($pipes[$i][0]);}
  $deadline=microtime(true)+10;do{$ready=true;foreach($jobs as $i=>$job)$ready=$ready&&is_file($dir.'/ready'.$i);if(!$ready)usleep(10000);}while(!$ready&&microtime(true)<$deadline);
  sn_check($ready,'independent workers ready');file_put_contents($dir.'/go','go');
  foreach($procs as $i=>$proc){$out=stream_get_contents($pipes[$i][1]);$err=stream_get_contents($pipes[$i][2]);fclose($pipes[$i][1]);fclose($pipes[$i][2]);$exit=proc_close($proc);sn_check($exit===0||!empty($jobs[$i]['crash'])&&$exit===23,'worker exit '.$err);$results[]=json_decode($out,true);}
  $count=is_file($dir.'/mail')?count(file($dir.'/mail',FILE_IGNORE_NEW_LINES)):0;return array($results,$count);
 } finally {foreach(glob($dir.'/*') as $file)unlink($file);rmdir($dir);}
}
