[$out,$sent]=sn_race(array($job,$job));sn_check($out[0]['ok']&&$out[1]['ok']&&$sent===1,'concurrent duplicate request sends once');sn_check(count(array_filter($out,static fn($r)=>!empty($r['noop'])))===1,'one concurrent noop');
