[$out,$sent]=sn_race(array(array('kind'=>'tick'),array('kind'=>'tick')));sn_check($sent===1&&sn_latest($race2['plan'])['status']==='sent','concurrent recovery workers send once');
add_filter('query',$recover,999);$crash=sn_fixture('crash@example.invalid');remove_filter('query',$recover,999);[$out,$sent]=sn_race(array(array('kind'=>'tick','crash'=>true)));sn_check($sent===1&&json_decode(sn_latest($crash['plan'])['payload_json'],true)['phase']==='attempt','worker process exit retains uncertain attempt');[$out,$sent]=sn_race(array(array('kind'=>'tick'),array('kind'=>'tick')));sn_check($sent===0,'worker restart cannot duplicate uncertain mail');
